// Convex → n8n. Verifies the HMAC signature on this webhook and spots repeats.
// LENDLOOP_OUTBOUND_SECRET comes from setting() below, never from this workflow.
// Settings come from n8n Variables ($vars) on n8n Cloud, or from the container env
// (n8n/.env) when self-hosted. Neither is stored in this workflow.
function setting(name, fallback) {
  let value = $vars?.[name];
  if (!value) {
    try {
      value = $env[name];
    } catch {
      // n8n Cloud blocks $env; the value must then come from Variables.
    }
  }
  if (value) return value;
  if (fallback !== undefined) return fallback;
  throw new Error(`${name} is not set: add it as an n8n Variable (n8n Cloud) or in n8n/.env (self-hosted)`);
}

const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const signature = String(headers['x-lendloop-signature'] ?? '');

// The signature covers the exact bytes Convex sent. Prefer the raw body; if it
// isn't available, Convex's compact JSON.stringify output re-serializes identically.
let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch {
  raw = JSON.stringify(item.json.body);
}

const secret = setting('LENDLOOP_OUTBOUND_SECRET');
const fresh = /^\d{1,12}$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
const given = Buffer.from(/^[0-9a-f]{64}$/i.test(signature) ? signature : '', 'hex');
const expected = secret
  ? crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest()
  : Buffer.alloc(0);
const valid =
  Boolean(secret) && fresh && given.length === 32 && crypto.timingSafeEqual(given, expected);

if (!valid) return [{ json: { valid: false } }];

const payload = JSON.parse(raw);
// eventIds this workflow already emailed (kept by "Remember event + sign ack").
// Static data persists for published (production) executions only.
const seen = $getWorkflowStaticData('global').seenEventIds ?? {};
return [{ json: { valid: true, duplicate: Boolean(seen[payload.eventId]), payload } }];

// Builds the email for this event. Uses only fields from the minimal payload.
// Settings come from n8n Variables ($vars) on n8n Cloud, or from the container env
// (n8n/.env) when self-hosted. Neither is stored in this workflow.
function setting(name, fallback) {
  let value = $vars?.[name];
  if (!value) {
    try {
      value = $env[name];
    } catch {
      // n8n Cloud blocks $env; the value must then come from Variables.
    }
  }
  if (value) return value;
  if (fallback !== undefined) return fallback;
  throw new Error(`${name} is not set: add it as an n8n Variable (n8n Cloud) or in n8n/.env (self-hosted)`);
}

const p = $json.payload;
const app = setting('LENDLOOP_APP_URL', 'http://localhost:3000');
const tool = p.loan.toolName;
const who = p.counterparty.firstName;
const dates = p.loan.startDate === p.loan.endDate
  ? p.loan.startDate
  : `${p.loan.startDate} to ${p.loan.endDate}`;

const messages = {
  'loan.requested': [
    `${who} wants to borrow your ${tool}`,
    `${who} asked to borrow your ${tool} (${dates}).\n\nApprove or decline: ${app}/requests?tab=lending`,
  ],
  'loan.cancelled': [
    `${who} cancelled a request for your ${tool}`,
    `${who} cancelled their request to borrow your ${tool} (${dates}). Nothing to do.`,
  ],
  'loan.approved': [
    `Approved: ${tool}`,
    `Good news: ${who} approved your request to borrow the ${tool} (${dates}).\n\nDetails: ${app}/requests?tab=borrowing`,
  ],
  'loan.declined': [
    `Declined: ${tool}`,
    `${who} declined your request to borrow the ${tool} (${dates}). Other neighbors may have one: ${app}/tools`,
  ],
  'loan.returned': [
    `Returned: ${tool}`,
    `${who} marked the ${tool} as returned. Thanks for borrowing responsibly!`,
  ],
};
const [subject, body] = messages[p.type] ?? [`LendLoop update: ${tool}`, `Your loan of the ${tool} changed.`];

return {
  json: {
    to: p.recipient.email,
    subject,
    text: `Hi ${p.recipient.firstName},\n\n${body}\n\n— LendLoop`,
  },
};

// Signs a request to Convex: HMAC-SHA256 over `${timestamp}.${rawBody}` with
// LENDLOOP_INBOUND_SECRET (see setting() below), never stored here.
// Settings come from n8n Variables ($vars) on n8n Cloud, or from the container env
// (n8n/.env) when self-hosted. Neither is stored in this workflow.
function setting(name, fallback) {
  let value = $vars?.[name];
  if (!value) {
    try {
      value = $env[name];
    } catch {
      // n8n Cloud blocks $env; the value must then come from Variables.
    }
  }
  if (value) return value;
  if (fallback !== undefined) return fallback;
  throw new Error(`${name} is not set: add it as an n8n Variable (n8n Cloud) or in n8n/.env (self-hosted)`);
}

const crypto = require('crypto');
function signed(body) {
  const raw = body === undefined ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', setting('LENDLOOP_INBOUND_SECRET'))
    .update(`${timestamp}.${raw}`)
    .digest('hex');
  return { raw, timestamp, signature };
}

// The email went out: remember the eventId so a Convex retry isn't emailed twice,
// keeping 30 days of IDs so static data stays small.
const staticData = $getWorkflowStaticData('global');
const seen = staticData.seenEventIds ?? {};
const { eventId } = $('Verify signature').first().json.payload;
seen[eventId] = Date.now();
const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
for (const [id, at] of Object.entries(seen)) if (at < cutoff) delete seen[id];
staticData.seenEventIds = seen;

return [{ json: signed({ eventId, status: 'sent', detail: 'Email sent' }) }];

// Signs a request to Convex: HMAC-SHA256 over `${timestamp}.${rawBody}` with
// LENDLOOP_INBOUND_SECRET (see setting() below), never stored here.
// Settings come from n8n Variables ($vars) on n8n Cloud, or from the container env
// (n8n/.env) when self-hosted. Neither is stored in this workflow.
function setting(name, fallback) {
  let value = $vars?.[name];
  if (!value) {
    try {
      value = $env[name];
    } catch {
      // n8n Cloud blocks $env; the value must then come from Variables.
    }
  }
  if (value) return value;
  if (fallback !== undefined) return fallback;
  throw new Error(`${name} is not set: add it as an n8n Variable (n8n Cloud) or in n8n/.env (self-hosted)`);
}

const crypto = require('crypto');
function signed(body) {
  const raw = body === undefined ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', setting('LENDLOOP_INBOUND_SECRET'))
    .update(`${timestamp}.${raw}`)
    .digest('hex');
  return { raw, timestamp, signature };
}

// Email failed after its retries: tell Convex (visible on the loan), then answer
// 502 so Convex's outbox retries the whole delivery later.
const { eventId } = $('Verify signature').first().json.payload;
const error = $input.first().json.error;
const detail = String(error?.message ?? error ?? 'Email failed').slice(0, 500);
return [{ json: signed({ eventId, status: 'failed', detail }) }];
